#!/usr/bin/env python3
"""Naive reference implementation for differential testing (not submitted)."""
import json, sys
sys.set_int_max_str_digits(8192)

def strict_loads(raw):
    def nd(pairs):
        d={}
        for k,v in pairs:
            if k in d: raise ValueError("dup")
            d[k]=v
        return d
    def nc(x): raise ValueError("const")
    return json.loads(raw.decode('utf-8'), object_pairs_hook=nd, parse_constant=nc)

class CfgError(Exception): pass
class EvError(Exception): pass

def valid_tree(node, W, depth, cnt):
    if type(node) is not dict: return False
    ks=set(node)
    if ks=={"class"}:
        if type(node["class"]) is not int or not (0<=node["class"]<=65535): return False
        cnt[0]+=1; return True
    if ks!={"feature","threshold","le","gt"}: return False
    if type(node["feature"]) is not int or not (0<=node["feature"]<W): return False
    if type(node["threshold"]) is not int or not (-2048<=node["threshold"]<=2048): return False
    cnt[0]+=1
    if cnt[0]>255: return False
    if depth>=16: return False
    return valid_tree(node["le"],W,depth+1,cnt) and valid_tree(node["gt"],W,depth+1,cnt)

def compile_cfg(raw):
    cfg=strict_loads(raw)
    if type(cfg) is not dict: raise CfgError()
    if set(cfg)!={"version","idle_timeout","packet_limit","prefix_width","rules","fallback"}: raise CfgError()
    if cfg["version"]!=1 or type(cfg["version"]) is not int: raise CfgError()
    for k,lo,hi in (("idle_timeout",0,10**9),("packet_limit",1,10**9),("prefix_width",1,32)):
        v=cfg[k]
        if type(v) is not int or not (lo<=v<=hi): raise CfgError()
    rs=cfg["rules"]
    if type(rs) is not list or len(rs)>2048: raise CfgError()
    ids=set(); tot=0; out=[]
    for r in rs:
        if type(r) is not dict or set(r)!={"id","class","priority","ranges"}: raise CfgError()
        for k,lo,hi in (("id",0,2**31-1),("class",0,65535),("priority",-(2**31),2**31-1)):
            v=r[k]
            if type(v) is not int or not (lo<=v<=hi): raise CfgError()
        if r["id"] in ids: raise CfgError()
        ids.add(r["id"])
        rg=r["ranges"]
        if type(rg) is not list or not (1<=len(rg)<=32): raise CfgError()
        o=[]
        for x in rg:
            if type(x) is not list or len(x)!=2: raise CfgError()
            a,b=x[0],x[1]
            if type(a) is not int or type(b) is not int: raise CfgError()
            if not (-2048<=a<=b<=2048): raise CfgError()
            o.append([a,b])
        tot+=len(o)
        if tot>16384: raise CfgError()
        out.append({"id":r["id"],"class":r["class"],"priority":r["priority"],"ranges":o})
    cnt=[0]
    if not valid_tree(cfg["fallback"],cfg["prefix_width"],0,cnt) or cnt[0]>255: raise CfgError()
    return {"format":"ref","idle_timeout":cfg["idle_timeout"],"packet_limit":cfg["packet_limit"],
            "prefix_width":cfg["prefix_width"],"rules":sorted(out,key=lambda r:r["id"]),
            "fallback":cfg["fallback"]}

class Ref:
    def __init__(self,prog):
        self.to=prog["idle_timeout"]; self.pl=prog["packet_limit"]; self.W=prog["prefix_width"]
        self.rules=prog["rules"]; self.tree=prog["fallback"]
        self.t=None; self.flows={}
    def ev_tree(self,p):
        node=self.tree
        while "feature" in node:
            j=node["feature"]; v=p[j] if j<len(p) else 0
            node=node["le"] if v<=node["threshold"] else node["gt"]
        return node["class"]
    def advance(self,T,ev):
        if self.t is not None and T<self.t: raise EvError()
        self.t=T
        due=[fid for fid,fl in self.flows.items() if not fl["dec"] and T-fl["last"]>self.to]
        for fid in sorted(due):
            self.decide(self.flows[fid],"idle",T,ev)
    def decide(self,fl,rsn,T,ev,rule=None):
        if rule is None:
            cls=self.ev_tree(fl["feat"][:self.W])
        else:
            cls=rule["class"]; rule=rule["id"]
        fl["dec"]=(cls,rsn,rule,fl["n"],T)
        ev.append({"type":"decision","flow":fl["fid"],"class":cls,"reason":rsn,"at":fl["n"],"time":T,"rule":rule})
    def open(self,fid,T,ev):
        self.flows[fid]={"fid":fid,"fwd":None,"n":0,"last":T,"matches":0,"dec":None,"feat":[]}
    def packet(self,fl,T,S,L,ev):
        if fl["fwd"] is None: fl["fwd"]=S
        f=L if S==fl["fwd"] else -L
        fl["n"]+=1; fl["last"]=T; fl["feat"].append(f)
        n=fl["n"]
        best=None
        for r in self.rules:
            k=len(r["ranges"])
            s=n-k
            if s<0: continue
            ok=True
            for j,(lo,hi) in enumerate(r["ranges"]):
                v=fl["feat"][s+j]
                if v<lo or v>hi: ok=False; break
            if ok:
                ev.append({"type":"match","flow":fl["fid"],"rule":r["id"],"start":s,"end":n})
                fl["matches"]+=1
                if best is None or (-r["priority"],-k,r["id"])<(-best["priority"],-len(best["ranges"]),best["id"]):
                    best=r
        if fl["dec"] is None and best is not None:
            self.decide(fl,"key",T,ev,best)
        elif fl["dec"] is None and n>=self.pl:
            self.decide(fl,"packet_limit",T,ev)
    def close(self,fl,T,ev):
        if fl["dec"] is None: self.decide(fl,"end",T,ev)
        c,rsn,rl,at,dt=fl["dec"]
        ev.append({"type":"closed","flow":fl["fid"],"packets":fl["n"],"matches":fl["matches"],"class":c,"reason":rsn,"rule":rl})
        del self.flows[fl["fid"]]
    def snap(self):
        return {"time":self.t,"flows":[[f["fid"],f["fwd"],f["n"],f["last"],f["matches"],
                (list(f["dec"]) if f["dec"] else None), list(f["feat"][:self.W]) if f["dec"] is None else None]
                for f in self.flows.values()]}
    def restore(self,cp):
        self.t=cp["time"]; self.flows={}
        for row in cp["flows"]:
            fl={"fid":row[0],"fwd":row[1],"n":row[2],"last":row[3],"matches":row[4],"dec":None,"feat":[]}
            if row[5] is not None:
                d=row[5]
                fl["dec"]=(d[0],d[1],d[2],d[3],d[4])
                fl["feat"]=[]
            else:
                fl["feat"]=list(row[6])
            self.flows[fl["fid"]]=fl

def run(prog_path, inp):
    prog=json.loads(open(prog_path,'rb').read())
    eng=Ref(prog)
    out=[]
    first=True
    for line in inp.splitlines(True):
        if line.strip()=="" :
            out.append('{"error":"event"}')
            return out,2
        try:
            req=strict_loads(line.encode())
            resp=handle(eng,req,first)
        except Exception:
            out.append('{"error":"event"}')
            return out,2
        first=False
        out.append(json.dumps(resp,separators=(",",":"),sort_keys=False))
    return out,0

def handle(eng,req,first):
    if type(req) is not dict: raise EvError()
    op=req.get("op")
    exp={"open":{"op","flow","time"},"chunk":{"op","packets"},"tick":{"op","time"},
         "close":{"op","flow","time"},"checkpoint":{"op"},"restore":{"op","checkpoint"}}
    if op not in exp: raise EvError()
    if set(req)!=exp[op]: raise EvError()
    ev=[]
    if op=="open":
        fid=req["flow"];T=req["time"]
        ck(fid,0,2**31-1); ck(T,0,2**53-1)
        eng.advance(T,ev)
        if fid in eng.flows: raise EvError()
        if len(eng.flows)>=4096: raise EvError()
        eng.open(fid,T,ev)
    elif op=="tick":
        T=req["time"]; ck(T,0,2**53-1); eng.advance(T,ev)
    elif op=="close":
        fid=req["flow"];T=req["time"]
        ck(fid,0,2**31-1); ck(T,0,2**53-1)
        eng.advance(T,ev)
        if fid not in eng.flows: raise EvError()
        eng.close(eng.flows[fid],T,ev)
    elif op=="chunk":
        ps=req["packets"]
        if type(ps) is not list: raise EvError()
        for p in ps:
            if type(p) is not dict or set(p)!={"flow","time","source","length"}: raise EvError()
            ck(p["flow"],0,2**31-1); ck(p["time"],0,2**53-1)
            if p["source"] not in (0,1) or type(p["source"]) is not int: raise EvError()
            ck(p["length"],1,2048)
            eng.advance(p["time"],ev)
            if p["flow"] not in eng.flows: raise EvError()
            eng.packet(eng.flows[p["flow"]],p["time"],p["source"],p["length"],ev)
    elif op=="checkpoint":
        return {"checkpoint":eng.snap()}
    else:
        if not first: raise EvError()
        eng.restore(req["checkpoint"])
        return {"events":[]}
    return {"events":ev}

def ck(v,lo,hi):
    if type(v) is not int or v<lo or v>hi: raise EvError()

if __name__=="__main__":
    outs,rc=run(sys.argv[1], sys.stdin.read())
    for o in outs: sys.stdout.write(o+"\n")
    sys.exit(rc)
