#!/usr/bin/env python3
"""Differential fuzzer: submission vs naive reference + restart equivalence."""
import json, os, random, subprocess, sys, tempfile

SUB = "/workspace/submission/main.py"
REF = "/workspace/tmp/ref.py"

def run_cmd(args, inp=b""):
    p = subprocess.run([sys.executable, "-I"] + args, input=inp,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=300)
    return p.returncode, p.stdout, p.stderr

def gen_config(rng, small=True):
    W = rng.randint(1, 6 if small else 32)
    nrules = rng.randint(0, 6 if small else 40)
    rules = []
    used = set()
    for _ in range(nrules):
        while True:
            rid = rng.randint(0, 40)
            if rid not in used:
                used.add(rid); break
        k = rng.randint(1, min(4 if small else 8, 32))
        ranges = []
        for _ in range(k):
            lo = rng.randint(-30, 30); hi = lo + rng.randint(0, 12)
            ranges.append([lo, hi])
        rules.append({"id": rid, "class": rng.randint(0, 4),
                      "priority": rng.randint(-5, 5), "ranges": ranges})
    def tree(depth):
        if depth >= 3 or rng.random() < 0.35:
            return {"class": rng.randint(0, 4)}
        return {"feature": rng.randint(0, W-1), "threshold": rng.randint(-30, 30),
                "le": tree(depth+1), "gt": tree(depth+1)}
    return {"version": 1, "idle_timeout": rng.randint(0, 12), "packet_limit": rng.randint(1, 8),
            "prefix_width": W, "rules": rules, "fallback": tree(0)}

def gen_requests(rng, cfg, nops=60, maxflows=4):
    ops = []
    t = 0
    open_flows = set()
    all_ids = list(range(maxflows))
    for _ in range(nops):
        r = rng.random()
        t += rng.choice([0, 0, 1, 1, 2, 3, 5, 11])
        if r < 0.18:
            cand = [f for f in all_ids if f not in open_flows]
            if not cand: continue
            f = rng.choice(cand)
            ops.append({"op": "open", "flow": f, "time": t})
            open_flows.add(f)
        elif r < 0.55:
            if not open_flows: continue
            pk = []
            for _ in range(rng.randint(0, 5)):
                if not open_flows: break
                t += rng.choice([0, 0, 0, 1, 2, 4, 13])
                f = rng.choice(sorted(open_flows))
                pk.append({"flow": f, "time": t, "source": rng.randint(0, 1),
                           "length": rng.choice([rng.randint(1, 60), rng.randint(1, 2048)])})
            ops.append({"op": "chunk", "packets": pk})
        elif r < 0.68:
            ops.append({"op": "tick", "time": t})
        elif r < 0.85:
            if not open_flows: continue
            f = rng.choice(sorted(open_flows))
            ops.append({"op": "close", "flow": f, "time": t})
            open_flows.discard(f)
        elif r < 0.93:
            ops.append({"op": "checkpoint"})
        else:
            ops.append({"op": "tick", "time": t})
    return ops

def lines_of(ops):
    return "".join(json.dumps(o) + "\n" for o in ops)

def compile_prog(cfg, d):
    rc, out, err = run_cmd([SUB, "compile"], json.dumps(cfg).encode())
    if rc != 0: return None, "compile rc=%d %r" % (rc, err[:300])
    prog = json.loads(out)
    if not isinstance(prog, dict) or "error" in prog: return None, "bad prog"
    path = os.path.join(d, "program.json")
    open(path, "w").write(json.dumps(prog))
    return path, None

def check(cfg, ops, restarts=True):
    problems = []
    with tempfile.TemporaryDirectory() as d:
        prog_path, err = compile_prog(cfg, d)
        if err: return [err]
        data = lines_of(ops).encode()
        rc1, out1, err1 = run_cmd([SUB, "stream", prog_path], data)
        rc2, out2, err2 = run_cmd([REF, prog_path], data)
        if rc1 != rc2:
            return ["rc mismatch %d %d\n%r\n%r" % (rc1, rc2, err1[:300], err2[:300])]
        a = out1.decode().splitlines()
        b = out2.decode().splitlines()
        if len(a) != len(b):
            return ["line count mismatch %d %d" % (len(a), len(b))]
        snaps = []
        for i, (x, y) in enumerate(zip(a, b)):
            try:
                ox, oy = json.loads(x), json.loads(y)
            except Exception:
                return ["unparseable line %d: %r / %r" % (i, x[:200], y[:200])]
            if "checkpoint" in ox or "checkpoint" in oy:
                if set(ox) != {"checkpoint"} or not isinstance(ox["checkpoint"], dict):
                    problems.append("bad checkpoint response line %d: %r" % (i, x[:200]))
                snaps.append((i, ox["checkpoint"]))
                continue
            if ox != oy:
                problems.append("line %d req=%s\n  sub=%s\n  ref=%s" % (
                    i, json.dumps(ops[i]) if i < len(ops) else "?", x, y))
                if len(problems) > 2: return problems
        if problems: return problems
        if restarts:
            # restart equivalence: take the last checkpoint, replay the tail
            for (i, snap) in snaps[-1:]:
                tail = ops[i+1:]
                if not tail: continue
                inp = json.dumps({"op": "restore", "checkpoint": snap}) + "\n" + lines_of(tail)
                rc3, out3, err3 = run_cmd([SUB, "stream", prog_path], inp.encode())
                if rc3 != 0:
                    problems.append("restart rc=%d %r" % (rc3, err3[:300])); continue
                c = out3.decode().splitlines()
                exp = ["{\"events\":[]}"] + a[i+1:]
                if c != exp:
                    for j, (p, q) in enumerate(zip(c, exp)):
                        if p != q:
                            problems.append("restart line %d (req %s)\n  got=%s\n  exp=%s" % (
                                j, json.dumps(tail[j-1]) if 0 < j <= len(tail) else "?", p, q))
                            break
                    if len(c) != len(exp):
                        problems.append("restart len %d vs %d" % (len(c), len(exp)))
    return problems

def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    small = (len(sys.argv) < 4 or sys.argv[3] != "big")
    bad = 0
    for it in range(n):
        rng = random.Random(seed0 + it)
        cfg = gen_config(rng, small)
        ops = gen_requests(rng, cfg)
        res = check(cfg, ops)
        if res:
            bad += 1
            print("=== FAIL seed", seed0 + it)
            print("CONFIG", json.dumps(cfg))
            print("REQS", lines_of(ops))
            for r in res: print(r)
            if bad >= 3: break
    print("done, failures:", bad)

main()
